SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_business WHERE 1=1
and YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name UNION SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_funds WHERE 1=1
AND YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name UNION SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_investment WHERE 1=1
AND YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name UNION SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_interest WHERE 1=1
AND YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name UNION SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_service WHERE 1=1
AND YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name

SELECT SUM(a.tradeAmount) total FROM ( SELECT * FROM ( SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_business WHERE 1=1
and YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name UNION SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_funds WHERE 1=1
AND YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name UNION SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_investment WHERE 1=1
AND YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name UNION SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_interest WHERE 1=1
AND YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name UNION SELECT rel_id pid, rel_name relName, TRAN_TYPE tranType, TRAN_DATE tranDate, TRADE_PRICE tradePrice, PRICING_POLICY pricingPolicy, TRADE_SUBJECT tradeSubject, MAJOR_TRADE majorTrade, SUM(TRADE_AMOUNT) tradeAmount FROM ins_tra_service WHERE 1=1
AND YEAR (TRAN_DATE) = #{pubYear}
GROUP BY rel_name ) t WHERE 1=1
AND t.tranType = #{tranType}
GROUP BY t.relName ) a

