SELECT SUM(t.majorTradecount) majorTradecount FROM ( SELECT count(MAJOR_TRADE) majorTradecount FROM ins_tra_business WHERE MAJOR_TRADE = 1
AND YEAR (TRAN_DATE) = #{pubYear}
AND TRAN_TYPE = #{tranType}
AND rel_name = #{relName}
UNION SELECT count(MAJOR_TRADE) majorTradecount FROM ins_tra_funds WHERE MAJOR_TRADE = 1
AND YEAR (TRAN_DATE) = #{pubYear}
AND TRAN_TYPE = #{tranType}
AND rel_name = #{relName}
UNION SELECT count(MAJOR_TRADE) majorTradecount FROM ins_tra_investment WHERE MAJOR_TRADE = 1
AND YEAR (TRAN_DATE) = #{pubYear}
AND TRAN_TYPE = #{tranType}
AND rel_name = #{relName}
UNION SELECT count(MAJOR_TRADE) majorTradecount FROM ins_tra_interest WHERE MAJOR_TRADE = 1
AND YEAR (TRAN_DATE) = #{pubYear}
AND TRAN_TYPE = #{tranType}
AND rel_name = #{relName}
UNION SELECT count(MAJOR_TRADE) majorTradecount FROM ins_tra_service WHERE MAJOR_TRADE = 1
AND YEAR (TRAN_DATE) = #{pubYear}
AND TRAN_TYPE = #{tranType}
AND rel_name = #{relName}
) t

